local _windowEvent = Instance.new("BindableEvent", script)
_windowEvent.Name = "_windowEvent"

local module = {}
local _windows = {}
local _containers = {}
local _panels = {}
local _openings = {}

local Window = require(script.Window)
local Container = require(script.Container)
local Panel = require(script.Panel)

function getWindow(name)
    if not name then
        return nil
    end
    return _windows[name]
end

function openWindow(name, ...)
    local idx = table.find(_openings, name)
    if idx then
        if idx == #_openings then
            return false
        end
        table.remove(_openings, idx)
    end
    table.insert(_openings, name)
    return true
end

function closeWindow(name, ...)
    local idx = table.find(_openings, name)
    if idx then
        table.remove(_openings, idx)
        return true
    end
end

function backWindow(name, ...)
    if name == _openings[#_openings] then
        table.remove(_openings, #_openings)
        return true
    end
end

function module:RegisterWindow(vm, v)
    local window = Window.new(vm, v)
    _windows[v] = window
end

function module:RegisterViewAsWindow(view, name)
    local window = Window.new(nil, name)
    window._content = view:GetContent()
    window._view = view
    _windows[name] = window
    return window
end

function module:GetWindow(window)
    return _windows[window]
end

function module:RegisterContainer(vm, v)
    local container = Container.new(vm, v)
    _containers[v] = container
end

function module:GetContainer(container)
    return _containers[container]
end

function module:RegisterPanel(vm, v)
    local panel = Panel.new(vm, v)
    _panels[v] = panel
    return panel
end

function module:RegisterViewAsPanel(view, name)
    local panel = Panel.new(nil, name)
    panel._content = view:GetContent()
    panel._view = view
    _panels[name] = panel
    return panel
end

function module:RegisterViewAsContainer(view, name)
    local container = Container.new(nil, name)
    container._content = view:GetContent()
    container._view = view
    _containers[name] = container
    return container
end

function module:GetPanel(panel)
    return _panels[panel]
end

function module:OpenWindow(name, ...)
    local res = openWindow(name, ...)
    if res then
        -- 关闭之前的窗口
        for i = 1, #_openings do
            if _openings[i] == name then
                break
            end
            local window = getWindow(_openings[i])
            if window and window._opening then
                local res = window:Close(...)
                if res then
                    _windowEvent:Fire("Close", _openings[i])
                else
                    warn(`[NezaUI] Window {_openings[i]} close error`)
                end
            end
        end
        local window = getWindow(name)
        if window and not window._opening then
            local res = window:Open(...)
            if res then
                _windowEvent:Fire("Open", name, ...)
                return true
            end
        end
    end
end

function module:CloseWindow(name, ...)
    local res = closeWindow(name, ...)
    if res then
        local window = getWindow(name)
        if window and window._opening then
            local res = window:Close(...)
            if res then
                _windowEvent:Fire("Close", name, ...)
                return true
            else
                warn(`[NezaUI] Window {name} close error`)
            end
        end
    end
end

function module:BackWindow(name, ...)
    local res = backWindow(name, ...)
    if res then
        local window = getWindow(name)
        if window and window._opening then
            local res = window:Close(...)
            if res then
                _windowEvent:Fire("Close", name, ...)
            else
                warn(`[NezaUI] Window {name} close error`)
            end
        end
        local window = getWindow(_openings[#_openings])
        if window and not window._opening then
            local res = window:Open(...)
            if res then
                _windowEvent:Fire("Open", _openings[#_openings], ...)
                return true
            end
        end
    end
end

function module:OnWindowOpened(name, callback)
    return _windowEvent.Event:Connect(function(cmd, windowName, ...)
        if cmd == "Open" and windowName == name then
            local suc, res = pcall(callback, ...)
            if not suc then
                warn(res)
                warn(debug.traceback())
            end
        end
    end)
end

function module:OnWindowClosed(name, callback)
    return _windowEvent.Event:Connect(function(cmd, windowName, ...)
        if cmd == "Close" and windowName == name then
            local suc, res = pcall(callback, ...)
            if not suc then
                warn(res)
                warn(debug.traceback())
            end
        end
    end)
end

function module:ShowPanel(container, name, ...)
    local container = _containers[container]
    local panel = _panels[name]
    assert(panel, `[NezaUI] Panel {name} not found`)
    assert(container, `[NezaUI] Container {container} not found`)
    if container then
        container:Show(panel, ...)
    end
end

function module:HidePanel(container, name, ...)
    local container = _containers[container]
    local panel = _panels[name]
    assert(panel, `[NezaUI] Panel {name} not found`)
    assert(container, `[NezaUI] Container {container} not found`)
    if container then
        container:Hide(panel, ...)
    end
end

function module:PopPanel(container, name, ...)
    local container = _containers[container]
    local panel = _panels[name]
    assert(panel, `[NezaUI] Panel {name} not found`)
    assert(container, `[NezaUI] Container {container} not found`)
    if container then
        container:Pop(panel, ...)
    end
end

function module:PushPanel(container, name, ...)
    local container = _containers[container]
    local panel = _panels[name]
    assert(panel, `[NezaUI] Panel {name} not found`)
    assert(container, `[NezaUI] Container {container} not found`)
    if container then
        container:Push(panel, ...)
    end
end

function module:CleanPanel(container, ...)
    local container = _containers[container]
    assert(container, `[NezaUI] Container {container} not found`)
    if container then
        container:Clean()
    end
end

function module:OnPanelShown(name, callback)
    return _windowEvent.Event:Connect(function(cmd, panelName, ...)
        if cmd == "Show" and panelName == name then
            local suc, res = pcall(callback, ...)
            if not suc then
                warn(res)
                warn(debug.traceback())
            end
        end
    end)
end

function module:OnPanelHidden(name, callback)
    return _windowEvent.Event:Connect(function(cmd, panelName, ...)
        if cmd == "Hide" and panelName == name then
            local suc, res = pcall(callback, ...)
            if not suc then
                warn(res)
                warn(debug.traceback())
            end
        end
    end)
end

return module